package io.dndroll.backup;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import io.dndroll.application.*;import java.time.Instant;
class CampaignEvidenceRebindTest {
 final CampaignEvidenceGraphTest f=new CampaignEvidenceGraphTest();final UUID target=UUID.randomUUID(),seed=UUID.randomUUID(),preview=UUID.randomUUID(),action=UUID.randomUUID();
 CampaignRemapPlan.Report proposal(List<CampaignEvidenceGraph.Row> rows){var maps=new LinkedHashMap<String,CampaignRemapPlan.Mapping>();maps.put("campaign",new CampaignRemapPlan.Mapping("campaign",f.campaign,target,0L));for(var r:rows){String ns=switch(r.table()){case "dice_roll","attack_preview","combat_action"->r.table();default->"character_card";};maps.put(ns+r.id(),new CampaignRemapPlan.Mapping(ns,r.id(),CampaignRemapPlan.proposal(seed,"a".repeat(64),f.campaign,target,ns,r.id()),null));}return new CampaignRemapPlan.Report(1,"BLOCKED",false,f.campaign,target,seed,"a".repeat(64),List.copyOf(maps.values()),List.of(),List.of(),List.of());}
 List<CampaignEvidenceGraph.Row> previewRows(){var rows=f.fixture();var a=new CombatService.Action(action,0,0,f.target,"SECRET_TEXT",0,f.helper,"SECRET_TEXT",null,"DM","PRIVATE_ACTOR",Instant.EPOCH,"",List.of());rows.add(new CampaignEvidenceGraph.Row("combat_action",action,0,null,null,f.target,f.helper,f.json.writeValueAsString(a)));var review=new AttackPreviewService.Create(UUID.randomUUID(),f.target,0,f.helper,0,"local",true,List.of(),List.of(),List.of(),List.of(),List.of(),List.of());var evidence=new AttackPreviewService.Evidence(review,f.card(f.target,0),f.card(f.helper,0),null,List.of("SECRET_TEXT"),null,null,null,action);var p=new AttackPreviewService.Preview(preview,0,"MANUAL_REQUIRED","PRIVATE_ACTOR",Instant.EPOCH,evidence,DiceService.fingerprint(f.json,List.of(evidence)),List.of());rows.add(new CampaignEvidenceGraph.Row("attack_preview",preview,0,null,null,f.target,f.helper,f.json.writeValueAsString(p)));return rows;}
 @Test void unknownShapeBlocks(){var rows=List.of(new CampaignEvidenceGraph.Row("unknown",UUID.randomUUID(),0,null,null,null,null,"{}"));assertFalse(CampaignEvidenceRebind.inspect(proposal(rows),rows,List.of()).consistent());}
 @Test void missingIdentityMappingBlocks(){var rows=f.fixture();var p=proposal(List.of());assertFalse(CampaignEvidenceRebind.inspect(p,rows,f.receipts()).consistent());}
 @Test void validRecordsRebindWithDedicatedAliasAndNoPrivateReport()throws Exception{var rows=f.fixture();var p=proposal(rows);var report=CampaignEvidenceRebind.inspect(p,rows,f.receipts());assertTrue(report.consistent(),report.toString());assertFalse(report.executable());assertFalse(report.toString().contains("PRIVATE_ACTOR"));assertFalse(report.toString().contains("SECRET_TEXT"));}
 @Test void previewHashUsesFullNewEvidenceAndPreservesReviewIdentity(){var rows=previewRows();var p=proposal(rows);var report=CampaignEvidenceRebind.inspect(p,rows,f.receipts());assertTrue(report.consistent(),report.toString());assertEquals(1,report.proofs().size());assertNotEquals(report.proofs().getFirst().sourceHash(),report.proofs().getFirst().targetHash());Collections.reverse(rows);assertEquals(report,CampaignEvidenceRebind.inspect(p,rows,f.receipts()));}
 @Test void corruptedSourceHashMustNotBeAccepted(){var rows=previewRows();var r=rows.getLast();var value=f.json.readValue(r.json(),AttackPreviewService.Preview.class);var p=new AttackPreviewService.Preview(value.id(),0,value.status(),value.actor(),value.at(),value.evidence(),"b".repeat(64),List.of());rows.set(rows.size()-1,new CampaignEvidenceGraph.Row(r.table(),r.id(),r.version(),null,null,r.characterId(),r.targetId(),f.json.writeValueAsString(p)));assertFalse(CampaignEvidenceRebind.inspect(proposal(rows),rows,f.receipts()).consistent());}
 @Test void typedOutputPreservesTextSourceControllersAndDedicatedAliases()throws Exception{
  var rows=f.fixture();var proposal=proposal(rows);var rebound=new CampaignEvidenceRebind(proposal).rebindRows(rows);var state=f.json.readValue(rebound.stream().filter(r->r.table().equals("stabilization_state")).findFirst().orElseThrow().json(),StabilizationService.State.class);var roll=f.json.readValue(rebound.stream().filter(r->r.table().equals("dice_roll")).findFirst().orElseThrow().json(),DiceService.Roll.class);
  assertEquals(state.latest().target().id(),state.id());assertEquals(roll.id(),state.latest().id());assertEquals(roll,state.latest().roll());assertEquals(state.latest().helper().id().toString(),roll.characterId());assertEquals(target,state.latest().target().campaignId());assertEquals(f.card(f.target,0).sheet(),state.latest().target().sheet());assertEquals(f.card(f.helper,0).controllers(),state.latest().helper().controllers());assertEquals("SECRET_TEXT",state.latest().reason());assertEquals("PRIVATE_ACTOR",roll.actor());assertNotEquals(f.target,state.id());assertEquals(f.fixture(),rows);
 }
 @Test void badProposalAndUnknownAdapterNameStayBlockedAndPrivate(){var rows=f.fixture();var p=proposal(rows);var bad=new CampaignRemapPlan.Report(p.formatVersion(),p.status(),false,p.sourceCampaign(),p.targetCampaign(),p.seed(),p.sourceDigest(),p.mappings(),p.aliases(),p.tables(),List.of("TARGET_ID_COLLISION"));assertFalse(CampaignEvidenceRebind.inspect(bad,rows,f.receipts()).consistent());var unknown=List.of(new CampaignEvidenceGraph.Row("SECRET_TABLE_NAME",f.target,0,null,null,null,null,"{}"));assertFalse(CampaignEvidenceRebind.inspect(p,unknown,List.of()).toString().contains("SECRET_TABLE_NAME"));} @Test void malformedDigestCannotEnterFailureReport(){var rows=f.fixture();var p=proposal(rows);var bad=new CampaignRemapPlan.Report(p.formatVersion(),p.status(),false,p.sourceCampaign(),p.targetCampaign(),p.seed(),"SECRET_DIGEST",p.mappings(),p.aliases(),p.tables(),p.blockers());var report=CampaignEvidenceRebind.inspect(bad,rows,f.receipts());assertFalse(report.consistent());assertFalse(report.toString().contains("SECRET_DIGEST"));}
 @Test void generatedEventMustRejectOccupiedSqlUuid()throws Exception{
  var rows=previewRows();var row=rows.stream().filter(r->r.table().equals("combat_action")).findFirst().orElseThrow();var a=f.json.readValue(row.json(),CombatService.Action.class);var ev=new CombatService.Event(UUID.randomUUID(),"PRIVATE_ACTOR",Instant.EPOCH,"VERDICT","HIT","SECRET_TEXT","",null,List.of(),false);var changed=new CombatService.Action(a.id(),1,1,a.characterId(),a.name(),a.sourceVersion(),a.targetId(),a.targetName(),a.attack(),a.visibility(),a.actor(),a.at(),a.verdict(),List.of(ev));rows.set(rows.indexOf(row),new CampaignEvidenceGraph.Row(row.table(),row.id(),1,null,null,row.characterId(),row.targetId(),f.json.writeValueAsString(changed)));var p=proposal(rows);var rebound=new CampaignEvidenceRebind(p).rebindRows(rows);var newAction=f.json.readValue(rebound.stream().filter(r->r.table().equals("combat_action")).findFirst().orElseThrow().json(),CombatService.Action.class);UUID occupied=newAction.events().getFirst().id();assertTrue(CampaignEvidenceRebind.inspect(p,rows,f.receipts()).consistent());assertFalse(CampaignEvidenceRebind.inspect(p,rows,f.receipts(),Set.of(occupied)).consistent());
 } @Test void previewProofUsesDeclaredJsonVersionWhenSqlHasNoVersionColumn(){var rows=previewRows();var old=rows.getLast();rows.set(rows.size()-1,new CampaignEvidenceGraph.Row(old.table(),old.id(),-1,null,null,old.characterId(),old.targetId(),old.json()));var report=CampaignEvidenceRebind.inspect(proposal(rows),rows,f.receipts());assertTrue(report.consistent());assertEquals(0,report.proofs().getFirst().version());}}
